"""Generate the local expressivity audit report after the installed-wheel tests."""
from pathlib import Path
import json
import xml.etree.ElementTree as ET
p=Path('validation/expressivity')
suite=ET.parse(p/'installed/installed-suite.xml').getroot();cases=suite.findall('.//testcase')
fails=sum(bool(c.findall('failure')+c.findall('error')) for c in cases);skip=sum(bool(c.findall('skipped')) for c in cases)
assert fails==0
reference=json.load(open(p/'independent-reference/summary.json'))
rows=[json.load(open(f)) for f in (p/'training').glob('*.json') if f.name!='widths.json']
assert len(rows)==168
summary=dict(passed=len(cases)-skip,failed=fails,skipped=skip,training_comparisons=len(rows),independent_reference=reference)
(p/'summary.json').write_text(json.dumps(summary,indent=2))
body=f'''<!doctype html><html><head><meta charset="utf-8"><title>QASP expressivity validation</title><style>body{{font:17px/1.6 system-ui;color:#17334e;background:#edf4fb;margin:0}}main{{max-width:1100px;margin:auto;padding:35px}}section{{background:white;padding:24px;margin:20px 0;border-radius:12px}}img{{max-width:100%}}a{{color:#075ca9}}table{{border-collapse:collapse;width:100%}}td,th{{text-align:left;padding:8px;border-bottom:1px solid #ddd}}</style></head><body><main><h1>QASP expressivity: width and training validation</h1><p>Local combined candidate · 10 November 2026 · no public release</p><section><h2>Installed package verification</h2><p><b>{summary['passed']} passed; {fails} failures; {skip} optional Kokkos skips.</b> This suite includes the previous configuration fixes and all expressivity regression tests. The installed package files were compared with source hashes. <a href="installed/installed-suite.log">Full test log</a> · <a href="installed/installed-suite.xml">JUnit results</a> · <a href="installed/environment.json">Package provenance</a></p></section><section><h2>What was checked</h2><ul><li>168 before/after optimization comparisons: classifier expectation and probability outputs, softmax and Born policies; fixed, scaled and neural encodings; Angle/IQP ansätze; widths 2 and 4 and seeds 17/31 for the primary matrix.</li><li>Additional backend comparisons use two qubits and commuting AngleAnsatz circuits: default.qubit, Lightning, mixed state, PennyLane MPS/TN, IQP TN/VN/auto and Pauli propagation. Unsupported probability backends are not used for classifier probability outputs.</li><li>Six optimizer updates per regression case; 30 epochs per worked notebook model. Policies optimize exact contextual-bandit expected reward; classifier objectives use logistic loss or negative log-likelihood.</li><li>Direct off-grid output reconstruction, complex conjugate symmetry, unchanged model weights/gradients/mode during analysis, independent snapshots, and moved learned frequencies versus fixed unscaled support.</li><li>Widths 2, 4, 6, 8, 10, 12, 14, 16: every coefficient independently checked for local cos(x) and parity cos(x)^n.</li></ul></section><section><h2>Independent algebraic reference</h2><p>{reference['models']} models, {reference['output_spectra']} output spectra and {reference['coefficient_entries']:,} coefficient entries across widths 2, 3, 4 and three seeds. Maximum coefficient error: {reference['max_coefficient_error']:.3g}. The reference uses spectral-projector density-matrix algebra independently of QASP's Fourier internals. <a href="independent-reference/summary.json">Reference summary</a></p></section><section><h2>Before and after training</h2><p>Classifier logistic loss: 0.760 → 0.410. Softmax expected bandit reward: 0.500 → 0.828; Born reward: 0.510 → 0.854. These are short correctness experiments, not convergence or learning-advantage claims. Active counts remained unchanged in these worked examples while predictions and spectra changed.</p><img src="figure-1.png" alt="Training loss and spectra before and after training"><p><a href="expressivity_training_executed.ipynb">Open executed notebook</a></p></section><section><h2>Expressivity versus qubit count</h2><img src="figure-2.png" alt="Allowed and active frequency counts versus qubit count"></section><section><h2>Scope and interpretation</h2><p>The analyzer computes the finite Fourier series of the current ideal circuit and affine readout. Softmax policies expose logits before softmax. It evaluates its own statevector circuit; model backend scalability does not transfer to this analysis. General phase grids and statevectors can grow exponentially. The 16-qubit case uses shared-input structure, not arbitrary independent neural projections.</p><p>Active frequency counts are threshold dependent, and are not a model-quality score. Learned scales may move support; fixed encodings can retain support while coefficients change. VN tests use exact enumeration and Pauli tests disable pruning. GPU, real distributed execution, noisy and approximate-backend error studies remain outside this CPU audit.</p><p><a href="installed/coverage-html/index.html">Coverage report</a> · <a href="summary.json">Machine-readable summary</a></p></section></main></body></html>'''
(p/'REPORT.html').write_text(body)
print(json.dumps({k:v for k,v in summary.items() if k!='independent_reference'}))
